import fs from 'node:fs';import {parseEnv} from 'node:util';import {createDecipheriv,randomUUID} from 'node:crypto';
const root='/Users/owoblo/Downloads/mission-control1/reputation-engine';const env={...parseEnv(fs.readFileSync(root+'/.env.partnership-runtime.local','utf8')),...parseEnv(fs.readFileSync(root+'/.env.google-mail.local','utf8'))};const out=root+'/artifacts/google-mail-release-20261109/delivery-check.json';
const headers={apikey:env.SUPABASE_KEY,Authorization:'Bearer '+env.SUPABASE_KEY};const response=await fetch(env.SUPABASE_URL+'/rest/v1/google_mail_connections?select=email,status,refresh_token_encrypted,campaign_enabled',{headers});if(!response.ok)throw Error('Connection storage '+response.status);const connections=await response.json();const domains=['moveswithsaturn.com','saturnstarconnect.com','saturnstarmoving.com','saturnstarpartners.com'];const emails=['john','johnny'].flatMap(u=>domains.map(d=>u+'@'+d));if(connections.length!==8||emails.some(e=>!connections.some(c=>c.email===e&&c.status==='connected'&&!c.campaign_enabled)))throw Error('Eight connected, campaign-disabled mailboxes required');
const tokens=new Map();for(const email of emails){const c=connections.find(c=>c.email===email);const [v,iv,tag,data]=c.refresh_token_encrypted.split('.');if(v!=='v1')throw Error('Token format');const decipher=createDecipheriv('aes-256-gcm',Buffer.from(env.GOOGLE_MAIL_TOKEN_KEY,'base64'),Buffer.from(iv,'base64url'));decipher.setAAD(Buffer.from(email));decipher.setAuthTag(Buffer.from(tag,'base64url'));const refresh=Buffer.concat([decipher.update(Buffer.from(data,'base64url')),decipher.final()]).toString();const r=await fetch('https://oauth2.googleapis.com/token',{method:'POST',body:new URLSearchParams({client_id:env.GOOGLE_MAIL_CLIENT_ID,client_secret:env.GOOGLE_MAIL_CLIENT_SECRET,grant_type:'refresh_token',refresh_token:refresh})});if(!r.ok)throw Error('Refresh failed '+email+' '+r.status);tokens.set(email,(await r.json()).access_token);}
async function api(email,path,body){const r=await fetch('https://gmail.googleapis.com/gmail/v1/users/me/'+path,{headers:{Authorization:'Bearer '+tokens.get(email),'Content-Type':'application/json'},...(body?{method:'POST',body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)});if(!r.ok){const err=await r.json();throw Error('Gmail '+email+' '+r.status+' '+(err.error?.status||''))}return r.json()}
for(const email of emails){const p=await api(email,'profile');if(p.emailAddress.toLowerCase()!==email)throw Error('Profile mismatch')};console.log('All eight refresh tokens and mailbox identities verified.');
let report=fs.existsSync(out)?JSON.parse(fs.readFileSync(out,'utf8')):{run:randomUUID(),startedAt:new Date().toISOString(),profilesVerified:8,messages:[]};const save=()=>fs.writeFileSync(out,JSON.stringify(report,null,2));save();
const h=(m,n)=>(m.payload?.headers||[]).filter(h=>h.name.toLowerCase()===n.toLowerCase()).map(h=>h.value).join('\n');
async function send(entry,threadId){if(entry.sendState)return;entry.sendState='attempting';save();const raw=['From: '+entry.from,'To: '+entry.to,'Subject: '+entry.subject,'Message-ID: <'+entry.messageId+'>','Date: '+new Date().toUTCString(),'MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8',...(entry.replyTo?['In-Reply-To: <'+entry.replyTo+'>','References: <'+entry.replyTo+'>']:[]),'','Saturn Star CRM owned-mailbox setup test. This verifies sending, receiving and email authentication. No action is needed. Test reference: '+report.run].join('\r\n');const sent=await api(entry.from,'messages/send',{raw:Buffer.from(raw).toString('base64url'),...(threadId?{threadId}:{})});entry.sendState='accepted';entry.sentId=sent.id;entry.sentThreadId=sent.threadId;save();}
for(let i=0;i<emails.length;i++){let entry=report.messages.find(m=>m.kind==='initial'&&m.from===emails[i]);if(!entry){entry={kind:'initial',from:emails[i],to:emails[(i+1)%emails.length],subject:'Saturn Star mailbox setup check '+report.run.slice(0,8)+' '+i,messageId:report.run+'.'+i+'@'+emails[i].split('@')[1]};report.messages.push(entry);save()}await send(entry)}console.log('Eight initial setup tests submitted to owned inboxes.');
async function receive(entry){if(entry.received)return true;if(!entry.actualMessageId){const sent=await api(entry.from,'messages/'+entry.sentId+'?format=metadata');entry.actualMessageId=h(sent,'Message-ID').replace(/[<>]/g,'');save();}const found=await api(entry.to,'messages?includeSpamTrash=true&maxResults=5&q='+encodeURIComponent('rfc822msgid:'+entry.actualMessageId));if(!found.messages?.length)return false;const m=await api(entry.to,'messages/'+found.messages[0].id+'?format=metadata');const auth=h(m,'Authentication-Results');entry.received={id:m.id,threadId:m.threadId,labels:m.labelIds,authenticationResults:auth,spf:/\bspf=pass\b/i.test(auth),dkim:/\bdkim=pass\b/i.test(auth),dmarc:/\bdmarc=pass\b/i.test(auth),messageId:h(m,'Message-ID').replace(/[<>]/g,'')};save();return true;}
for(let round=0;round<12;round++){let missing=0;for(const entry of report.messages.filter(m=>m.kind==='initial'))if(!await receive(entry))missing++;if(!missing)break;await new Promise(r=>setTimeout(r,5000))}
for(const initial of report.messages.filter(m=>m.kind==='initial'&&m.received)){let reply=report.messages.find(m=>m.kind==='reply'&&m.replyTo===initial.received.messageId);if(!reply){reply={kind:'reply',from:initial.to,to:initial.from,subject:initial.subject,messageId:randomUUID()+'@'+initial.to.split('@')[1],replyTo:initial.received.messageId};report.messages.push(reply);save()}await send(reply,initial.received.threadId)}console.log('Replies submitted for delivered tests.');
for(let round=0;round<12;round++){let missing=0;for(const entry of report.messages.filter(m=>m.kind==='reply'))if(!await receive(entry))missing++;if(!missing)break;await new Promise(r=>setTimeout(r,5000))}
report.completedAt=new Date().toISOString();report.summary={connected:8,accepted:report.messages.filter(m=>m.sendState==='accepted').length,received:report.messages.filter(m=>m.received).length,inbox:report.messages.filter(m=>m.received?.labels?.includes('INBOX')).length,spfPass:report.messages.filter(m=>m.received?.spf).length,dkimPass:report.messages.filter(m=>m.received?.dkim).length,dmarcPass:report.messages.filter(m=>m.received?.dmarc).length,repliesThreaded:report.messages.filter(m=>m.kind==='reply'&&m.received?.threadId===report.messages.find(x=>x.actualMessageId===m.replyTo)?.sentThreadId).length};save();console.log(JSON.stringify(report.summary));
